        match store.Read() with
        | OpenYardDocumentRead.Found document -> OpenYardDocumentLoaded.Loaded(start document)
        | OpenYardDocumentRead.Missing -> OpenYardDocumentLoaded.DocumentMissing(start empty)
        | OpenYardDocumentRead.ReadFailed reason -> OpenYardDocumentLoaded.LoadFailed reason

    let private withEntry (session: OpenYardDocumentSession) (entry: OpenYardEntry) =
        { session with Working = { session.Working with Entries = Map.add entry.Id entry session.Working.Entries } }

    /// Adds an entry at the workflow's initial state, in memory. Refused while a save is unknown.
    let create (session: OpenYardDocumentSession) (id: OpenYardId) : OpenYardCreated =
        match session.Pending with
        | Some pending -> OpenYardCreated.Unreconciled pending
        | None when Map.containsKey id session.Working.Entries -> OpenYardCreated.AlreadyExists id
        | None -> OpenYardCreated.Created(withEntry session { Id = id; Revision = 0L; State = OpenYardState.Closed })

    /// Decides one command against one entry and applies it to the working copy. `expected`, when
    /// given, is the entry revision the caller acted on. Refused while a save is unknown.
    let apply (rules: OpenYardRules) (session: OpenYardDocumentSession) (id: OpenYardId) (expected: int64 option) (command: OpenYardCommand) : OpenYardCommandOutcome =
        match session.Pending, Map.tryFind id session.Working.Entries, expected with
        | Some pending, _, _ -> OpenYardCommandOutcome.Unreconciled pending
        | None, None, _ -> OpenYardCommandOutcome.EntryNotFound id
        | None, Some entry, Some revision when revision <> entry.Revision -> OpenYardCommandOutcome.EntryStale(id, revision, entry.Revision)
        | None, Some entry, _ ->
            match OpenYardTransition.decide rules entry.State command with
            | Error refusal -> OpenYardCommandOutcome.Refused(refusal, entry)
            | Ok decision ->
                OpenYardCommandOutcome.Applied(withEntry session { entry with Revision = entry.Revision + 1L; State = decision.Next }, decision)

    let private write (store: IOpenYardDocumentStore) (session: OpenYardDocumentSession) (operation: OpenYardOperationId) =
        match store.Write(operation, session.Stored.Version, session.Working) with
        | OpenYardDocumentWrite.Written version ->
            let stored = { session.Working with Version = Some version }
            OpenYardSaveOutcome.Saved(operation, version), { session with Stored = stored; Working = stored }
        | OpenYardDocumentWrite.VersionMismatch current -> OpenYardSaveOutcome.Unresolved(sprintf "another write moved the document to version %A" current), session
        | OpenYardDocumentWrite.WriteFailed error when error.ProvenNotApplied -> OpenYardSaveOutcome.NotSaved error.Reason, session
        | OpenYardDocumentWrite.WriteFailed _ -> OpenYardSaveOutcome.OutcomeUnknown operation, { session with Pending = Some operation }

    /// Writes the working copy under `operation`, expecting the version last read or written. A
    /// failure not proven to be without effect is unknown: it is returned as unknown and blocks
