    let save (store: IOpenYardDocumentStore) (session: OpenYardDocumentSession) (operation: OpenYardOperationId) : OpenYardSaveOutcome * OpenYardDocumentSession =
        match session.Pending with
        | Some pending -> OpenYardSaveOutcome.Unreconciled pending, session
        | None -> write store session operation

    let private inspect (store: IOpenYardDocumentStore) (session: OpenYardDocumentSession) (operation: OpenYardOperationId) =
        let settled = { session with Pending = if session.Pending = Some operation then None else session.Pending }
        match store.Read() with
        | OpenYardDocumentRead.ReadFailed reason -> OpenYardReconciled.StillUnknown reason, session
        | read ->
            let current = match read with | OpenYardDocumentRead.Found document -> document | _ -> empty
            if current.Version = session.Stored.Version then OpenYardReconciled.NotApplied, settled
            else OpenYardReconciled.Unresolved "the document moved and the plan leaves the idempotency scope unresolved", session

    /// Inspects the stored document to settle one save whose outcome was unknown. Nothing is written.
    let reconcile (store: IOpenYardDocumentStore) (session: OpenYardDocumentSession) (operation: OpenYardOperationId) : OpenYardReconciled * OpenYardDocumentSession =
