        | OpenYardCommandOutcome.EntryNotFound _ -> None
        | OpenYardCommandOutcome.EntryStale _ -> None
        | OpenYardCommandOutcome.Applied _ | OpenYardCommandOutcome.Unreconciled _ -> None
